/**
 * Fail-Closed Gating Logic
 * 
 * This module implements the critical requirement:
 * "Gravito MUST be consulted for certain classes of tasks, otherwise fail closed."
 * 
 * This transforms Gravito from a "powerful component" to a "mandatory utility layer."
 * 
 * Key principle: No approval token = No action allowed on regulated surfaces
 */

import { z } from 'zod';

// ============================================================================
// TYPES
// ============================================================================

/**
 * Surfaces that REQUIRE Gravito governance (fail-closed)
 */
export type RegulatedSurface = 
  | 'medical'
  | 'financial'
  | 'legal'
  | 'hr'
  | 'compliance';

/**
 * Surfaces that SHOULD have Gravito governance (fail-open with warning)
 */
export type AdvisorySurface =
  | 'sales'
  | 'support'
  | 'marketing';

/**
 * All surface types
 */
export type Surface = RegulatedSurface | AdvisorySurface | 'general';

/**
 * Approval token that MUST be passed to action tools
 */
export interface ApprovalToken {
  tokenId: string;

