// ============================================================================
// TYPES
// ============================================================================

export interface MCPContent {
  content: Array<{ type: string; text: string }>;
}

export interface ExecutionContext {
  apiKey?: string;
  clientIp?: string;
  userAgent?: string;
  /**
   * TRUSTED authenticated tenant, resolved by the HTTP handler from a validated
   * inference credential (provisioned tenant key → org-<id>/user-<id>, spoof-
   * proof). Additive + optional: existing call sites compile unchanged and leave
   * it undefined. It is the ONLY input that can raise the canonical verdict
   * receipt's tenant binding to `authenticated_tenant`.
   */
  authenticatedTenant?: { tenantId: string; source: string };
}

// Tool arguments arrive as parsed JSON from JSON-RPC — untyped at the boundary.
// Each handler validates its own inputs. This is the explicit trust boundary.
type ToolArgs = Record<string, unknown>;
type ToolHandler = (args: ToolArgs, ctx: ExecutionContext) => Promise<MCPContent>;

// ============================================================================
// HELPER: Wrap result in MCP content format
// ============================================================================

function mcpText(data: unknown): MCPContent {
  return { content: [{ type: 'text', text: JSON.stringify(data) }] };
}

// ============================================================================
// HELPERS: Narrow untyped JSON-RPC args to the shapes downstream APIs declare
// ============================================================================

/** Coerce an arg to a string, matching template-literal semantics (nullish → ''). */
function asText(value: unknown): string {
  if (typeof value === 'string') return value;
  if (value === undefined || value === null) return '';
  return String(value);
}

/** Coerce an arg to a number; non-numeric, non-finite and zero values fall back. */
function asNumber(value: unknown, fallback: number): number {
  const n = typeof value === 'number' ? value : typeof value === 'string' ? Number(value) : NaN;
  return Number.isFinite(n) && n !== 0 ? n : fallback;
}

/** Narrow an arg to a plain JSON object. */
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Narrow an arg to an array of strings, dropping non-string entries. */
function asStringArray(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((entry): entry is string => typeof entry === 'string') : [];
}

/**
 * Narrow a caller-supplied surface name against the gate's own surface lists.
 * The lists are passed in so the source of truth stays in fail-closed-gate.
 */
function isKnownSurface(
  value: string,
  regulated: readonly string[],
  advisory: readonly string[],
): value is Surface {
  return value === 'general' || regulated.includes(value) || advisory.includes(value);
}

/** Safe wrapper — catches errors and returns them as standardized MCP content */
async function safeTool(fn: () => Promise<MCPContent>, toolName?: string): Promise<MCPContent> {
  try {
    return await fn();
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error);
    const errorCode = classifyError(error);
    generalLog.error(`[ToolExecutor] ${toolName || 'unknown'} error (${errorCode}):`, error);
    return mcpText(mcpError(message || 'Tool execution failed', errorCode, toolName));
  }
}

