  recordStateSignal: async (args) => mcpText(await ceRecordStateSignal(args as any)),
  assessPressure: async (args) => mcpText(await ceAssessPressure(args as any)),
  detectConflict: async (args) => mcpText(await ceDetectConflict(args as any)),
